<?php
namespace App\Services\AiSales;use App\Models\{AiSalesAutomationRule,AiSalesCompany,AiSalesTask};
class AutomationEngine {
 public function run(string $trigger,array $context=[]):array{$rules=AiSalesAutomationRule::where('is_active',true)->where('trigger',$trigger)->get();$executed=0;$skipped=0;foreach($rules as $rule){if(!$this->matches($rule->conditions??[],$context)){$skipped++;continue;}$company=isset($context['company_id'])?AiSalesCompany::find($context['company_id']):null;foreach($rule->actions??[] as $action){if(($action['type']??null)==='create_task'&&$company){AiSalesTask::create(['company_id'=>$company->id,'type'=>$action['task_type']??'follow_up','title'=>$action['title']??'AI Sales follow-up','description'=>$action['description']??null,'priority'=>$action['priority']??'medium','status'=>'open','due_at'=>now()->addDays((int)($action['due_in_days']??1))]);}}$rule->increment('run_count');$rule->update(['last_run_at'=>now()]);$executed++;}return ['rules_executed'=>$executed,'rules_skipped'=>$skipped];}
 private function matches(array $conditions,array $context):bool{foreach($conditions as $c){$field=$c['field']??null;$op=$c['operator']??'=';$expected=$c['value']??null;if(!$field)continue;$actual=data_get($context,$field);$ok=match($op){'='=>$actual==$expected,'!='=>$actual!=$expected,'>'=>is_numeric($actual)&&$actual>$expected,'>='=>is_numeric($actual)&&$actual>=$expected,'<'=>is_numeric($actual)&&$actual<$expected,'<='=>is_numeric($actual)&&$actual<=$expected,'in'=>in_array($actual,(array)$expected,true),'contains'=>is_string($actual)&&str_contains(mb_strtolower($actual),mb_strtolower((string)$expected)),default=>false};if(!$ok)return false;}return true;}
}
